<template><div class="app-container"><el-alert title="内容批次冻结的是：一个问题、同受众来源角色、事实替换、共享结构和唯一变化轴。生成专属页会在下一阶段承接真实六槽位运行；本页先用于查询与回看已冻结批次。" type="info" :closable="false" class="mb16" /><el-form ref="queryRef" :model="queryParams" :inline="true" v-show="showSearch" label-width="72px"><el-form-item label="租户"><el-input v-model="queryParams.tenantId" clearable style="width:170px" /></el-form-item><el-form-item label="客户标识"><el-input v-model="queryParams.clientId" clearable /></el-form-item><el-form-item label="问题标识"><el-input v-model="queryParams.problemId" clearable /></el-form-item><el-form-item label="受众"><el-select v-model="queryParams.audienceType" clearable style="width:170px"><el-option label="B2B美业老板" value="B2B_BEAUTY_OWNER"/><el-option label="B2C门店消费者" value="B2C_STORE_CONSUMER"/></el-select></el-form-item><el-form-item><el-button type="primary" icon="Search" @click="handleQuery">搜索</el-button><el-button icon="Refresh" @click="resetQuery">重置</el-button></el-form-item></el-form><el-row class="mb8"><right-toolbar v-model:showSearch="showSearch" @queryTable="getList" /></el-row><el-table v-loading="loading" :data="briefList"><el-table-column label="客户" min-width="160"><template #default="s">{{ s.row.clientName || '-' }}<small v-if="s.row.clientCode">（{{ s.row.clientCode }}）</small></template></el-table-column><el-table-column label="要解决的问题" prop="problemStatement" min-width="280" show-overflow-tooltip/><el-table-column label="受众" prop="audienceType" width="165"/><el-table-column label="唯一变化轴" prop="variantAxis" min-width="170" show-overflow-tooltip/><el-table-column label="最近作业" prop="latestJobStatus" width="120"><template #default="s"><el-tag :type="jobTag(s.row.latestJobStatus)">{{ s.row.latestJobStatus || '未请求' }}</el-tag></template></el-table-column><el-table-column label="候选" prop="candidateCount" width="75"/><el-table-column label="创建时间" prop="createdAt" width="170"/><el-table-column label="操作" fixed="right" width="150"><template #default="s"><el-button link type="primary" icon="View" @click="detail(s.row)">冻结详情</el-button><el-button link type="success" icon="Edit" @click="review(s.row)" v-hasPermi="['topic:candidate:list']">审阅候选</el-button></template></el-table-column></el-table><pagination v-show="total>0" :total="total" v-model:page="queryParams.pageNum" v-model:limit="queryParams.pageSize" @pagination="getList"/><el-dialog title="内容批次冻结详情" v-model="open" width="760px"><el-descriptions :column="1" border><el-descriptions-item label="问题">{{ form.problemStatement }}</el-descriptions-item><el-descriptions-item label="内容路线"><div class="pre">{{ form.contentRouteSnapshot }}</div></el-descriptions-item><el-descriptions-item label="共享不变项"><div class="pre">{{ form.sharedCoreSnapshot }}</div></el-descriptions-item><el-descriptions-item label="唯一变化轴">{{ form.variantAxis }}</el-descriptions-item></el-descriptions><template #footer><el-button @click="open=false">关闭</el-button></template></el-dialog></div></template>
<script setup lang="ts">import { getCurrentInstance, reactive, ref, toRefs } from 'vue'; import type { ComponentInternalInstance } from 'vue'; import { useRouter } from 'vue-router'; import { getTopicContentBrief, listTopicContentBrief } from '@/api/topic/contentBrief'; import type { TopicContentBrief, TopicContentBriefQueryParams } from '@/types'; const { proxy }=getCurrentInstance() as ComponentInternalInstance; const router=useRouter(); const briefList=ref<TopicContentBrief[]>([]),loading=ref(true),showSearch=ref(true),total=ref(0),open=ref(false); const data=reactive({form:{} as TopicContentBrief,queryParams:{pageNum:1,pageSize:10,tenantId:'local-preview'} as TopicContentBriefQueryParams}); const {form,queryParams}=toRefs(data); function getList(){loading.value=true;listTopicContentBrief(queryParams.value).then(r=>{briefList.value=r.rows;total.value=r.total}).finally(()=>loading.value=false)} function handleQuery(){queryParams.value.pageNum=1;getList()} function resetQuery(){proxy?.resetForm('queryRef');queryParams.value.tenantId='local-preview';handleQuery()} function detail(row:TopicContentBrief){getTopicContentBrief(row.id as string).then(r=>{form.value=r.data||{};open.value=true})} function review(row:TopicContentBrief){router.push({path:'/topic/candidate-review',query:{briefId:row.id}})} function jobTag(s?:string){return s==='SUCCEEDED'?'success':s==='FAILED'?'danger':s==='RUNNING'?'warning':''} getList();</script><style scoped>.pre{white-space:pre-wrap;line-height:1.7}small{color:#909399;margin-left:4px}</style>
